        &mut self,
        sequence_number: u64,
        handle: ReceiptHandle,
        now: u64,
    ) -> Result<&mut Message, Error> {
        self.messages
            .get_mut(&sequence_number)
            .filter(|message| message.handle == Some(handle) && message.state(now) == State::InFlight)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ReceiptHandleExpired,
                    format!("receipt handle {handle} is not the current handle of an in-flight message"),
                )
            })
    }

    pub fn delete_in_flight(
        &mut self,
        sequence_number: u64,
        handle: ReceiptHandle,
        now: u64,
    ) -> Result<(), Error> {
        self.in_flight_mut(sequence_number, handle, now)?;
        self.remove(sequence_number);
        Ok(())
    }

