        &mut self,
        sequence_number: u64,
        handle: ReceiptHandle,
        timeout: u32,
        now: u64,
    ) -> Result<(), Error> {
        let message = self.in_flight_mut(sequence_number, handle, now)?;
        message.visible_at = now + u64::from(timeout);
        Ok(())
    }
}
